        var titles = await WhenPopularTitlesQueried(100);

        ThenTitlesAre(titles, "TravelPost", "TechPost");
    }

    private async Task GivenBlogWithPosts(string blogName, params PostSeed[] seeds)
    {
        var blog = new Blog
        {
            Name = blogName,
            Posts = new List<Post>(),
            Contributors = new List<Contributor>()
        };
        foreach (var seed in seeds)
        {
            blog.Posts.Add(new Post { Title = seed.Title, Views = seed.Views });
        }
        _database.Blogs.Add(blog);
        await _database.SaveChangesAsync();
    }

    private Task<List<string>> WhenPopularTitlesQueried(int minViews) =>
        BlogQueries.PopularTitles(_database, minViews, CancellationToken.None);

    private static void ThenTitlesAre(List<string> actual, params string[] expected)
    {
        Assert.Equal(expected, actual);
    }
