using System.Linq;
using System.Threading.Tasks;
using EfFixtures;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Xunit;

public class BlogQueriesTotalViewsPerBlogTests : IAsyncLifetime
{
    private SqliteConnection _connection = null!;
    private BlogContext _database = null!;

    public async Task InitializeAsync()
    {
        _connection = new SqliteConnection("DataSource=:memory:");
        await _connection.OpenAsync();
        _database = new BlogContext(new DbContextOptionsBuilder<BlogContext>().UseSqlite(_connection).Options);
        await _database.Database.EnsureCreatedAsync();
    }

    public async Task DisposeAsync()
    {
        await _database.DisposeAsync();
        await _connection.DisposeAsync();
    }

    [Fact]
    public async Task GivenNoBlogs_WhenTotalingViewsPerBlog_ThenResultIsEmpty()
    {
        var totals = await WhenTotalingViewsPerBlog();

        Assert.Empty(totals);
    }

    [Fact]
    public async Task GivenBlogWithoutPosts_WhenTotalingViewsPerBlog_ThenTotalIsZero()
    {
        var blog = GivenBlog("Alpha");
        await _database.SaveChangesAsync();

        var totals = await WhenTotalingViewsPerBlog();

        Assert.Equal(new[] { new BlogTotal("Alpha", 0) }, totals);
    }

    [Fact]
    public async Task GivenBlogWithPosts_WhenTotalingViewsPerBlog_ThenTotalIsSumOfViews()
    {
        var blog = GivenBlog("Alpha");
        GivenPost(blog, "First", 10);
        GivenPost(blog, "Second", 32);
        await _database.SaveChangesAsync();

        var totals = await WhenTotalingViewsPerBlog();

        Assert.Equal(new[] { new BlogTotal("Alpha", 42) }, totals);
    }

    [Fact]
    public async Task GivenSeveralBlogs_WhenTotalingViewsPerBlog_ThenResultsAreOrderedByName()
    {
        var beta = GivenBlog("Beta");
        GivenPost(beta, "B1", 5);
        var alpha = GivenBlog("Alpha");
        GivenPost(alpha, "A1", 7);
        await _database.SaveChangesAsync();

        var totals = await WhenTotalingViewsPerBlog();

        Assert.Equal(
            new[] { new BlogTotal("Alpha", 7), new BlogTotal("Beta", 5) },
            totals);
    }

    [Fact]
    public async Task GivenBlogWithContributors_WhenTotalingViewsPerBlog_ThenContributorsDoNotAffectTotal()
    {
        var blog = GivenBlog("Alpha");
        GivenPost(blog, "First", 10);
        GivenContributor(blog, "Ada");
        GivenContributor(blog, "Grace");
        await _database.SaveChangesAsync();

        var totals = await WhenTotalingViewsPerBlog();

        Assert.Equal(new[] { new BlogTotal("Alpha", 10) }, totals);
    }

    private Blog GivenBlog(string name)
    {
        var blog = new Blog { Name = name, Posts = new List<Post>(), Contributors = new List<Contributor>() };
        _database.Blogs.Add(blog);
        return blog;
    }

    private static void GivenPost(Blog blog, string title, int views)
    {
        blog.Posts.Add(new Post { Title = title, Views = views });
    }

    private static void GivenContributor(Blog blog, string name)
    {
        blog.Contributors.Add(new Contributor { Name = name });
    }

    private Task<List<BlogTotal>> WhenTotalingViewsPerBlog() =>
        BlogQueries.TotalViewsPerBlog(_database, CancellationToken.None);
}
