    private BlogContext _database = null!;

    public async Task InitializeAsync()
    {
        _connection = new SqliteConnection("DataSource=:memory:");
        _connection.Open();

        var options = new DbContextOptionsBuilder<BlogContext>()
            .UseSqlite(_connection)
            .Options;

        _database = new BlogContext(options);
        await _database.Database.EnsureCreatedAsync();
    }

    public async Task DisposeAsync()
    {
        await _database.DisposeAsync();
        await _connection.DisposeAsync();
    }

    [Fact]
    public async Task GivenNoPosts_WhenPopularTitlesQueried_ThenResultIsEmpty()
    {
        var titles = await WhenPopularTitlesQueried(0);

        Assert.Empty(titles);
    }

    [Fact]
    public async Task GivenPostsAboveThreshold_WhenPopularTitlesQueried_ThenTitlesOrderedByViewsDescending()
    {
        await GivenBlogSaved("Tech", ("Low", 20), ("High", 300), ("Mid", 120));

        var titles = await WhenPopularTitlesQueried(10);

        ThenTitlesAre(titles, "High", "Mid", "Low");
    }

    [Fact]
    public async Task GivenPostWithViewsEqualToThreshold_WhenPopularTitlesQueried_ThenPostIsExcluded()
    {
        await GivenBlogSaved("Tech", ("AtThreshold", 50), ("AboveThreshold", 51));

        var titles = await WhenPopularTitlesQueried(50);

        ThenTitlesAre(titles, "AboveThreshold");
    }

    [Fact]
    public async Task GivenPostsBelowThreshold_WhenPopularTitlesQueried_ThenResultIsEmpty()
    {
        await GivenBlogSaved("Tech", ("Quiet", 3), ("Quieter", 1));

        var titles = await WhenPopularTitlesQueried(10);

        Assert.Empty(titles);
    }

    [Fact]
    public async Task GivenPostsFromMultipleBlogs_WhenPopularTitlesQueried_ThenIncludesMatchingPostsFromAllBlogs()
    {
        await GivenBlogSaved("Tech", ("TechHit", 500));
        await GivenBlogSaved("Travel", ("TravelHit", 200), ("TravelMiss", 5));

        var titles = await WhenPopularTitlesQueried(100);

        ThenTitlesAre(titles, "TechHit", "TravelHit");
    }

    [Fact]
    public async Task GivenCancelledToken_WhenPopularTitlesQueried_ThenThrowsOperationCanceledException()
    {
        using var cancellationSource = new CancellationTokenSource();
        cancellationSource.Cancel();

        await Assert.ThrowsAnyAsync<OperationCanceledException>(
            () => BlogQueries.PopularTitles(_database, 0, cancellationSource.Token));
    }

    private async Task GivenBlogSaved(string name, params (string Title, int Views)[] posts)
    {
        _database.Blogs.Add(new Blog
        {
            Name = name,
            Posts = new List<Post>(posts.ConvertAll(post => new Post { Title = post.Title, Views = post.Views })),
        });
        await _database.SaveChangesAsync();
    }

    private Task<List<string>> WhenPopularTitlesQueried(int minViews) =>
        BlogQueries.PopularTitles(_database, minViews, CancellationToken.None);

    private void ThenTitlesAre(List<string> actual, params string[] expected) =>
        Assert.Equal(expected, actual);
}
