using EfFixtures;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Xunit;

public class BlogQueriesTotalViewsPerBlogTests : IAsyncLifetime
{
    private SqliteConnection _connection = null!;
    private BlogContext _database = null!;

    public async Task InitializeAsync()
    {
        _connection = new SqliteConnection("DataSource=:memory:");
        await _connection.OpenAsync();

        var options = new DbContextOptionsBuilder<BlogContext>()
            .UseSqlite(_connection)
            .Options;
        _database = new BlogContext(options);
        await _database.Database.EnsureCreatedAsync();
    }

    public async Task DisposeAsync()
    {
        await _database.DisposeAsync();
        await _connection.DisposeAsync();
    }

    [Fact]
    public async Task GivenNoBlogs_WhenGettingTotalViewsPerBlog_ThenResultIsEmpty()
    {
        var totals = await WhenGettingTotalViewsPerBlog();

        Assert.Empty(totals);
    }

    [Fact]
    public async Task GivenBlogWithoutPosts_WhenGettingTotalViewsPerBlog_ThenTotalIsZero()
    {
        await GivenBlog("Quiet", new Dictionary<string, int>());

        var totals = await WhenGettingTotalViewsPerBlog();

        var total = Assert.Single(totals);
        ThenTotalIs(total, "Quiet", 0);
    }

    [Fact]
    public async Task GivenBlogWithPosts_WhenGettingTotalViewsPerBlog_ThenViewsAreSummed()
    {
        await GivenBlog("Busy", new Dictionary<string, int>
        {
            ["First"] = 10,
            ["Second"] = 25,
            ["Third"] = 7
        });

        var totals = await WhenGettingTotalViewsPerBlog();

        var total = Assert.Single(totals);
        ThenTotalIs(total, "Busy", 42);
    }

    [Fact]
    public async Task GivenMultipleBlogs_WhenGettingTotalViewsPerBlog_ThenEachBlogHasItsOwnTotal()
    {
        await GivenBlog("Alpha", new Dictionary<string, int> { ["A1"] = 1, ["A2"] = 2 });
        await GivenBlog("Beta", new Dictionary<string, int> { ["B1"] = 100 });

        var totals = await WhenGettingTotalViewsPerBlog();

        Assert.Equal(2, totals.Count);
        ThenTotalIs(totals[0], "Alpha", 3);
        ThenTotalIs(totals[1], "Beta", 100);
    }

    [Fact]
    public async Task GivenBlogsAddedOutOfOrder_WhenGettingTotalViewsPerBlog_ThenResultsAreOrderedByName()
    {
        await GivenBlog("Charlie", new Dictionary<string, int> { ["C1"] = 3 });
        await GivenBlog("Alpha", new Dictionary<string, int> { ["A1"] = 1 });
        await GivenBlog("Bravo", new Dictionary<string, int> { ["B1"] = 2 });

        var totals = await WhenGettingTotalViewsPerBlog();

        Assert.Equal(new[] { "Alpha", "Bravo", "Charlie" }, totals.ConvertAll(t => t.BlogName));
    }

    [Fact]
    public async Task GivenBlogWithContributors_WhenGettingTotalViewsPerBlog_ThenTotalIsNotMultiplied()
    {
        await GivenBlogWithContributors("Team", new Dictionary<string, int>
        {
            ["P1"] = 5,
            ["P2"] = 15
        }, "Ann", "Bob", "Cy");

        var totals = await WhenGettingTotalViewsPerBlog();

        var total = Assert.Single(totals);
        ThenTotalIs(total, "Team", 20);
    }

    private async Task GivenBlog(string name, Dictionary<string, int> postViewsByTitle) =>
        await GivenBlogWithContributors(name, postViewsByTitle);

    private async Task GivenBlogWithContributors(
        string name,
        Dictionary<string, int> postViewsByTitle,
        params string[] contributorNames)
    {
        var blog = new Blog { Name = name, Posts = new List<Post>(), Contributors = new List<Contributor>() };
        foreach (var (title, views) in postViewsByTitle)
            blog.Posts.Add(new Post { Title = title, Views = views });
        foreach (var contributorName in contributorNames)
            blog.Contributors.Add(new Contributor { Name = contributorName });

        _database.Blogs.Add(blog);
        await _database.SaveChangesAsync();
        _database.ChangeTracker.Clear();
    }

    private Task<List<BlogTotal>> WhenGettingTotalViewsPerBlog() =>
        BlogQueries.TotalViewsPerBlog(_database, CancellationToken.None);

    private static void ThenTotalIs(BlogTotal total, string expectedName, int expectedViews)
    {
        Assert.Equal(expectedName, total.BlogName);
        Assert.Equal(expectedViews, total.TotalViews);
    }
}
