        await using var database = GivenDatabase(connection);

        var blog = new Blog { Name = "Testing" };
        blog.Posts.Add(new Post { Title = "Most viewed", Views = 100 });
        blog.Posts.Add(new Post { Title = "At minimum", Views = 50 });
        blog.Posts.Add(new Post { Title = "Less viewed", Views = 75 });
        blog.Posts.Add(new Post { Title = "Below minimum", Views = 49 });
        database.Blogs.Add(blog);
        await database.SaveChangesAsync();

        var titles = await WhenGettingPopularTitles(database, 50);

        Assert.Equal(new[] { "Most viewed", "Less viewed" }, titles);
    }

    [Fact]
    public async Task GivenNoPostsAboveMinimum_WhenGettingPopularTitles_ThenReturnsEmptyList()
    {
        using var connection = GivenOpenConnection();
        await using var database = GivenDatabase(connection);

        var blog = new Blog { Name = "Testing" };
        blog.Posts.Add(new Post { Title = "At minimum", Views = 50 });
        blog.Posts.Add(new Post { Title = "Below minimum", Views = 49 });
        database.Blogs.Add(blog);
