    {
        var options = new DbContextOptionsBuilder<BlogContext>()
            .UseSqlite(connection)
            .Options;

        var database = new BlogContext(options);
        database.Database.EnsureCreated();
        return database;
    }

    private static Task<List<string>> WhenGettingPopularTitles(
        BlogContext database,
        int minViews) =>
        BlogQueries.PopularTitles(database, minViews, CancellationToken.None);
