using System.Threading.Tasks;
using EfFixtures;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Xunit;

public class PopularTitlesTests : IAsyncLifetime
{
    private SqliteConnection _connection;
    private BlogContext _database;

    public async Task InitializeAsync()
    {
        _connection = new SqliteConnection("Data Source=:memory:");
        await _connection.OpenAsync();

        var options = new DbContextOptionsBuilder<BlogContext>()
            .UseSqlite(_connection)
            .Options;
        _database = new BlogContext(options);
        await _database.Database.EnsureCreatedAsync();
    }

    public async Task DisposeAsync()
    {
        await _database.DisposeAsync();
        await _connection.DisposeAsync();
    }

    private async Task<Blog> GivenBlogWithPosts(string blogName, params (string Title, int Views)[] posts)
    {
        var blog = new Blog { Name = blogName, Posts = new List<Post>(), Contributors = new List<Contributor>() };
        foreach (var (title, views) in posts)
        {
            blog.Posts.Add(new Post { Title = title, Views = views });
        }
        _database.Blogs.Add(blog);
        await _database.SaveChangesAsync();
        return blog;
    }

    private async Task<List<string>> WhenPopularTitlesAreQueried(int minViews) =>
        await BlogQueries.PopularTitles(_database, minViews, CancellationToken.None);

    [Fact]
    public async Task PopularTitles_ReturnsOnlyPostsAboveMinViews()
    {
        await GivenBlogWithPosts("Tech Blog",
            ("Popular Post", 100),
            ("Barely There", 50),
            ("Obscure Post", 10));

        var titles = await WhenPopularTitlesAreQueried(minViews: 40);

        Assert.Equal(new[] { "Popular Post", "Barely There" }, titles);
    }

    [Fact]
    public async Task PopularTitles_OrdersTitlesByViewsDescending()
    {
        await GivenBlogWithPosts("Tech Blog",
            ("Middle", 200),
            ("Top", 900),
            ("Low", 100));

        var titles = await WhenPopularTitlesAreQueried(minViews: 0);

        Assert.Equal(new[] { "Top", "Middle", "Low" }, titles);
    }

    [Fact]
    public async Task PopularTitles_ExcludesPostsAtExactlyMinViews()
    {
        await GivenBlogWithPosts("Tech Blog",
            ("Boundary", 50),
            ("Above", 51));

        var titles = await WhenPopularTitlesAreQueried(minViews: 50);

        Assert.Equal(new[] { "Above" }, titles);
    }

    [Fact]
    public async Task PopularTitles_ReturnsPostsAcrossBlogs()
    {
        await GivenBlogWithPosts("Blog A", ("A Hit", 500));
        await GivenBlogWithPosts("Blog B", ("B Hit", 400));

        var titles = await WhenPopularTitlesAreQueried(minViews: 100);

        Assert.Equal(new[] { "A Hit", "B Hit" }, titles);
    }

    [Fact]
    public async Task PopularTitles_ReturnsEmptyListWhenNoPostsQualify()
    {
        await GivenBlogWithPosts("Quiet Blog", ("Nobody Read This", 1));

        var titles = await WhenPopularTitlesAreQueried(minViews: 1000);

        Assert.Empty(titles);
    }

    [Fact]
    public async Task PopularTitles_ReturnsEmptyListWhenNoPostsExist()
    {
        var titles = await WhenPopularTitlesAreQueried(minViews: 0);

        Assert.Empty(titles);
    }
}
