    private static async Task<BlogContext> GivenDatabase()
    {
        var connection = new SqliteConnection("Data Source=:memory:");
        await connection.OpenAsync();
        var options = new DbContextOptionsBuilder<BlogContext>().UseSqlite(connection).Options;
        var database = new BlogContext(options);
        await database.Database.EnsureCreatedAsync();
        return new DisposableBlogContext(database, connection);
    }

    private static async Task<Blog> GivenBlog(BlogContext database, string name, params (string Title, int Views)[] posts)
    {
        var blog = new Blog { Name = name, Posts = new List<Post>(), Contributors = new List<Contributor>() };
        foreach (var (title, views) in posts)
        {
            blog.Posts.Add(new Post { Title = title, Views = views });
        }
        database.Blogs.Add(blog);
        await database.SaveChangesAsync();
        return blog;
    }

    private sealed class DisposableBlogContext : BlogContext
    {
        private readonly BlogContext _inner;
        private readonly SqliteConnection _connection;

        public DisposableBlogContext(BlogContext inner, SqliteConnection connection) : base(null!)
        {
            _inner = inner;
            _connection = connection;
        }

        public override Microsoft.EntityFrameworkCore.DbSet<Blog> Blogs => _inner.Blogs;
        public override Microsoft.EntityFrameworkCore.DbSet<Post> Posts => _inner.Posts;
        public override Microsoft.EntityFrameworkCore.DbSet<Contributor> Contributors => _inner.Contributors;

        public override async ValueTask DisposeAsync()
        {
            await _inner.DisposeAsync();
            await _connection.DisposeAsync();
        }
    }
}
