```

Actually, a cleaner approach — keep a single `BlogContext` backed by one open SQLite connection, and dispose the connection after the test. Since `BlogContext` has a public constructor taking `DbContextOptions<BlogContext>`, I can hold the connection in a field.

```csharp
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using EfFixtures;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Xunit;

public class BlogQueriesTests : IAsyncLifetime
{
    private readonly SqliteConnection _connection = new("Data Source=:memory:");
    private BlogContext _database = null!;

    public async Task InitializeAsync()
    {
        await _connection.OpenAsync();
        var options = new DbContextOptionsBuilder<BlogContext>()
            .UseSqlite(_connection)
            .Options;
        _database = new BlogContext(options);
        await _database.Database.EnsureCreatedAsync();
    }

    public async Task DisposeAsync()
    {
        await _database.DisposeAsync();
        await _connection.DisposeAsync();
    }

    private BlogContext GivenContext() => _database;

    private Blog GivenBlog(string name, params (string Title, int Views)[] posts)
    {
        var blog = new Blog { Name = name };
        blog.Posts.AddRange(posts.Select(p => new Post { Title = p.Title, Views = p.Views }));
        _database.Blogs.Add(blog);
        return blog;
    }

    private async Task GivenSeeded(Func<BlogContext, Task> seed)
    {
        await seed(_database);
        await _database.SaveChangesAsync();
    }

    [Fact]
    public async Task GivenNoPosts_WhenGettingPopularTitles_ThenEmptyList()
    {
        var titles = await BlogQueries.PopularTitles(GivenContext(), 0, CancellationToken.None);
        Assert.Empty(titles);
    }

    [Fact]
    public async Task GivenPostsAboveAndBelowMin_WhenGettingPopularTitles_ThenOnlyAboveThresholdReturned()
    {
        await GivenSeeded(async db =>
        {
            var blog = new Blog { Name = "Tech" };
            blog.Posts.Add(new Post { Title = "Low", Views = 5 });
            blog.Posts.Add(new Post { Title = "Mid", Views = 10 });
            blog.Posts.Add(new Post { Title = "High", Views = 100 });
            db.Blogs.Add(blog);
            await Task.CompletedTask;
        });

        var titles = await BlogQueries.PopularTitles(GivenContext(), 10, CancellationToken.None);

        Assert.Equal(new[] { "High" }, titles);
