        {
            var blog = new Blog { Name = "Tech" };
            blog.Posts.Add(new Post { Title = "Few", Views = 15 });
            blog.Posts.Add(new Post { Title = "Most", Views = 500 });
            blog.Posts.Add(new Post { Title = "Some", Views = 50 });
            db.Blogs.Add(blog);
            await Task.CompletedTask;
        });

        var titles = await BlogQueries.PopularTitles(GivenContext(), 0, CancellationToken.None);

        Assert.Equal(new[] { "Most", "Some", "Few" }, titles);
    }

    [Fact]
    public async Task GivenPostsAcrossBlogs_WhenGettingPopularTitles_ThenAllTitlesIncluded()
